import { useForm } from 'react-hook-form';
import { useQuery } from '@tanstack/react-query';

const EditUserForm = ({ userId }: { userId: string }) => {
  const { data, isLoading, isError } = useQuery({
    queryKey: ['user', userId],
    queryFn: () => fetchUser(userId)
  });

  const { register, handleSubmit, reset, formState: { errors } } = useForm<{
    name: string;
    email: string;
  }>({
    defaultValues: async () => ({
      name: data?.name ?? '',
      email: data?.email ?? ''
    })
  });

  useEffect(() => {
    if (data) {
      reset({ name: data.name, email: data.email });
    }
  }, [data, reset]);

  if (isLoading) return <p>Loading...</p>;
  if (isError) return <p>Error loading user</p>;

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <input {...register('name', { required: true })} />
      <input {...register('email', { required: true })} />
      <button type="submit">Save</button>
    </form>
  );
};

const EditUserForm = ({ userId }: { userId: string }) => {
  const queryClient = useQueryClient();

  const updateMutation = useMutation({
    mutationFn: (updatedUser) =>
      fetch(`/api/users/${userId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedUser)
      }).then(res => res.json()),
    onSuccess: (updatedUser) => {
      queryClient.setQueryData(['user', userId], updatedUser);
      queryClient.invalidateQueries({ queryKey: ['users'] });
    }
  });

  const onSubmit = handleSubmit((data) => {
    updateMutation.mutate(data);
  });

  return (
    <form onSubmit={onSubmit}>
      <input {...register('name')} />
      <input {...register('email')} />
      <button type="submit" disabled={updateMutation.isPending}>
        {updateMutation.isPending ? 'Saving...' : 'Save'}
      </button>
      {updateMutation.isError && (
        <p>Failed to save: {updateMutation.error.message}</p>
      )}
    </form>
  );
};

const updateMutation = useMutation({
  mutationFn: updateUser,
  onMutate: async (newUser) => {
    await queryClient.cancelQueries({ queryKey: ['user', userId] });

    const previousUser = queryClient.getQueryData(['user', userId]);

    queryClient.setQueryData(['user', userId], newUser);

    return { previousUser };
  },
  onError: (err, newUser, context) => {
    queryClient.setQueryData(['user', userId], context?.previousUser);
  },
  onSettled: () => {
    queryClient.invalidateQueries({ queryKey: ['user', userId] });
  }
});

const onSubmit = handleSubmit(async (data) => {
  try {
    await updateMutation.mutateAsync(data);
  } catch (error) {
    if (error instanceof ApiError && error.errors) {
      Object.entries(error.errors).forEach(([field, message]) => {
        setError(field as keyof FormData, {
          type: 'server',
          message: message as string
        });
      });
    }
  }
});

// React Component Example with Hooks
import React, { useState, useEffect, useCallback } from 'react';

function DataFetcher({ endpoint }) {
  // State management with useState
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // useCallback for memoized fetch function
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(endpoint);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      setData(result);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [endpoint]);

  // useEffect for side effects
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">Error: {error}</div>;

  return (
    <div className="data-container">
      <h2>Fetched Data</h2>
      <pre>{JSON.stringify(data, null, 2)}</pre>
    </div>
  );
}

export default DataFetcher;

